  const plans=d.kimThread200?.plans||[];const plan=[...plans].reverse().find(p=>p&&['pending','maybe','agreed'].includes(p.status)&&!p.story228);if(!plan)return'';
  const l=norm(lastThem);const label=[plan.what||plan.activity,plan.when].filter(Boolean).join(' ');
