          for(const m of d.messages)if(m?.from==='me'&&ids.has(m.mid))m.status='seen';
          d.queue=(d.queue||[]).filter(x=>!ids.has(x.mid));d.typing=false;d.pending=false;d.unread=M?.dataset?.dm===id?false:true;d.lastInboundAt=at;d.awaitingPlayer=true;
          try{remember('dm_reply',{celebrityId:id,celebrity:a.name,text:reply,inReplyTo:text,turnId:job.mid,story228:true})}catch{}
          save0();if(M?.dataset?.dm===id){try{refreshOpenDm(id)}catch{}}else{try{addNotif(`${a.name} replied to you.`,'dm',{celebrityId:id})}catch{}}
